\mathrm{df\text{-}strong\text{-}field\text{-}closure}\vdash\;\begin{aligned}
\mathsf{ImageField}(\mathcal K,\mathcal L,h,S)&\leftrightarrow\mathsf{Emb}(\mathcal K,\mathcal L,h)\land\mathsf{Subfield}(S,\mathcal L)\\
&\quad\land\forall b\in L\;(b\in S\leftrightarrow\exists a\in K\;h(a)=b),\\
\mathsf{SAlgCl}(\mathcal K,\mathcal L,h,S)&\leftrightarrow\mathsf{AlgCl}(\mathcal K,\mathcal L,h)\land\mathsf{ImageField}(\mathcal K,\mathcal L,h,S),\\
\mathsf{SRealCl}(\mathcal K,O,\mathcal L,P,h,S)&\leftrightarrow\mathsf{RealCl}(\mathcal K,O,\mathcal L,P,h)\land\mathsf{ImageField}(\mathcal K,\mathcal L,h,S).
\end{aligned}
